<script setup lang="ts">
import type {SnmpConfig,SnmpCredentials} from '../tools/snmp'
const props=defineProps<{en:boolean;config:SnmpConfig;credentials:SnmpCredentials;disabled:boolean;running:boolean}>(),emit=defineEmits<{run:[];stop:[]}>(),t=(zh:string,en:string)=>props.en?en:zh
const operations=[['get','GET'],['getnext','GETNEXT'],['getbulk','GETBULK'],['walk','WALK'],['overview','Overview'],['interfaces','Interfaces']]
</script>
<template><div class="panel-title"><h2>{{t('SNMP 只读查询','Read-only SNMP')}}</h2><span>v2c / v3 USM</span></div><form @submit.prevent="emit('run')">
<label for="snmp-target">{{t('设备 IP / 域名','Device IP / hostname')}}</label><input id="snmp-target" v-model="config.target" required maxlength="253" spellcheck="false">
<div class="field-pair"><div><label for="snmp-port">{{t('端口','Port')}}</label><input id="snmp-port" type="number" min="1" max="65535" v-model.number="config.port" required></div><div><label for="snmp-version">{{t('版本','Version')}}</label><select id="snmp-version" v-model="config.version"><option value="2c">v2c</option><option value="3">v3 USM</option></select></div></div>
<label for="snmp-operation">{{t('操作','Operation')}}</label><select id="snmp-operation" v-model="config.operation"><option v-for="[id,label] in operations" :key="id" :value="id">{{id==='overview'?t('设备概览','Overview'):id==='interfaces'?t('接口观察','Interfaces'):label}}</option></select>
<template v-if="!['overview','interfaces'].includes(config.operation)"><label for="snmp-oids">OID {{t('（空格或逗号分隔；WALK 单子树）','(space/comma separated; one WALK subtree)')}}</label><textarea id="snmp-oids" :value="config.oids.join(' ')" @input="config.oids=($event.target as HTMLTextAreaElement).value.split(/[\s,]+/).filter(Boolean)"></textarea><small>sysName · sysDescr · sysObjectID · sysUpTime · system · ifTable · ifXTable</small></template>
<label v-if="config.version==='2c'" for="snmp-community">Community<input id="snmp-community" data-sensitive type="password" v-model="credentials.community" autocomplete="off" maxlength="255" required></label>
<template v-else><label for="snmp-user">{{t('用户名','Username')}}</label><input id="snmp-user" v-model="config.username" required maxlength="32"><label for="snmp-context">Context</label><input id="snmp-context" v-model="config.context" maxlength="255"><label for="snmp-security">{{t('安全级别','Security level')}}</label><select id="snmp-security" v-model="config.security_level"><option value="auth_priv">authPriv · {{config.auth_protocol.toUpperCase()}} / AES-128</option><option value="auth_no_priv">authNoPriv · {{config.auth_protocol.toUpperCase()}}</option><option value="no_auth_no_priv">noAuthNoPriv</option></select><template v-if="config.security_level!=='no_auth_no_priv'"><label for="snmp-auth">{{t('认证算法','Authentication')}}</label><select id="snmp-auth" v-model="config.auth_protocol"><option value="sha256">SHA-256</option><option value="sha1">SHA-1 · {{t('旧设备兼容','Legacy compatibility')}}</option></select><label for="snmp-auth-password">{{t('认证密码','Authentication password')}}</label><input id="snmp-auth-password" data-sensitive type="password" v-model="credentials.auth_password" autocomplete="off" minlength="8" maxlength="1024" required><template v-if="config.security_level==='auth_priv'"><label for="snmp-privacy-password">{{t('AES-128 加密密码','AES-128 privacy password')}}</label><input id="snmp-privacy-password" data-sensitive type="password" v-model="credentials.privacy_password" autocomplete="off" minlength="8" maxlength="1024" required></template></template></template>
<p>{{t('Community 在当前页面保留，方便重复查询；v3 密码启动后清空。凭据不进入现场配置或导出。','Community stays on this page for repeated queries; v3 passwords are cleared after start. Credentials are excluded from profiles and exports.')}}</p>
<div class="field-pair"><div><label for="snmp-timeout">{{t('响应超时 / ms','Response timeout / ms')}}</label><input id="snmp-timeout" type="number" min="100" max="10000" v-model.number="config.timeout_ms" required></div><div><label for="snmp-retries">{{t('额外重试','Extra retries')}}</label><input id="snmp-retries" type="number" min="0" max="3" v-model.number="config.retries" required></div></div>
<div v-if="config.operation==='interfaces'" class="field-pair"><div><label for="snmp-interval">{{t('采样间隔 / ms','Sample interval / ms')}}</label><input id="snmp-interval" type="number" min="1000" max="60000" v-model.number="config.interval_ms"></div><div><label for="snmp-samples">{{t('采样数（0 持续）','Samples (0 continuous)')}}</label><input id="snmp-samples" type="number" min="0" max="100000" v-model.number="config.samples"></div></div>
<details><summary>{{t('期限与结果边界','Deadline and result limits')}}</summary><label>{{t('总查询 / 单次接口快照期限（秒）','Query / interface snapshot deadline (s)')}}<input type="number" min="1" max="60" v-model.number="config.deadline_secs"></label><label>max-repetitions<input type="number" min="1" max="50" v-model.number="config.max_repetitions"></label><label>{{t('结果项上限','Result limit')}}<input type="number" min="1" max="10000" v-model.number="config.max_results"></label><label>{{t('解码字节上限','Decoded byte limit')}}<input type="number" min="1024" max="4194304" v-model.number="config.max_bytes"></label></details>
<button class="primary" type="submit" :disabled="disabled">{{t('开始 SNMP','Start SNMP')}}</button><button class="stop" type="button" v-if="running" @click="emit('stop')">{{t('停止并保留结果','Stop and retain results')}}</button></form></template>
